// Automatically reads Lambda Function URLs generated by Amplify Gen 2 (amplify_outputs.json)
// or falls back to Vite env variables if set explicitly.
const outputsModules = import.meta.glob('../../amplify_outputs.json', { eager: true });
const amplifyOutputs = Object.values(outputsModules)[0]?.default ?? Object.values(outputsModules)[0] ?? null;

export function getQuoteApiUrl() {
  return import.meta.env.VITE_QUOTE_API_URL || amplifyOutputs?.custom?.quoteApiUrl || '';
}

export function getReviewsApiUrl() {
  return import.meta.env.VITE_REVIEWS_API_URL || amplifyOutputs?.custom?.reviewsApiUrl || '';
}
